/**
 * Timing-contract regression tests for issue #4859 — a COMPLETE RSC payload must
 * server-side render within the same macrotask turn.
 *
 * THE CONTRACT PINNED HERE
 * ========================
 * Given an RSC payload that is complete (every Flight row — including rows for
 * promises that were already resolved when the payload was serialized — delivered
 * as a single stream chunk) and a warm client renderer (manifests already loaded,
 * the steady state of a long-running renderer process), the decode path used by
 * SSR (`getReactServerComponent` → `transformRSCNodeStream` → `createFromNodeStream`)
 * must resolve to a fully-settled element tree using MICROTASKS ONLY:
 *
 *   - strictly before a `setImmediate` armed just before decode starts, AND
 *   - strictly before a `setTimeout(..., 0)` armed at the same moment.
 *
 * Tripwire choice: the setImmediate tripwire is the stricter and primary one.
 * Delivery of a fully-buffered Node stream and settlement of already-resolved
 * thenables both happen in the nextTick/microtask tier, before the event loop
 * reaches its check phase — so a healthy decode never lets a pre-armed immediate
 * fire. A regression that adds even ONE macrotask hop (a stray setImmediate, an
 * async `import()` during module resolution, a genuinely pending thenable) fires
 * it deterministically. The setTimeout(0) tripwire alone could MISS a
 * single-setImmediate regression (the check phase runs before the next timers
 * phase, and the 1 ms timer threshold may not have elapsed yet), but it matches
 * the issue's headline contract, costs nothing, and catches slower regressions —
 * so both are armed.
 *
 * Cold-cache exception (documented, deliberately NOT a zero-macrotask assertion):
 * the very first decode in a process pays the manifest `fs.readFile` inside
 * `createFromReactOnRailsNodeStream` — macrotasks by nature. That cost is bounded
 * to manifest loading, happens before React ever sees the tree, and must never
 * change the SHAPE of the SSR output; the cold-cache test pins exactly that, and
 * that a process becomes warm after a single decode.
 *
 * End-to-end consequence (the user-visible half — issue cases 5–6): with a
 * complete payload, `streamServerRenderedReactComponent`'s output contains the
 * real markup and NO Suspense fallback HTML, no pending-boundary marker
 * (`<!--$?-->`), no `<template` placeholder, and no boundary-completion runtime
 * (`$RC`) anywhere — and the whole response completes within a small, bounded
 * number of macrotask turns. Fizz schedules its flushes via setImmediate by
 * design, and setImmediate-vs-setTimeout(0) ordering from a non-I/O context is
 * nondeterministic in Node, so a literal before-setTimeout(0) assertion on the
 * first flushed CHUNK would be flaky by construction; the bounded-turn budget +
 * output-shape assertions fail loudly on a real regression without that
 * flakiness. The negative control (a payload whose Suspense content is genuinely
 * pending at first flush) proves these assertions can fail: it must produce the
 * fallback + pending markers at first flush and the completion script later.
 *
 * HOW REAL THIS PIPELINE IS
 * =========================
 * Everything below the payload source is real: real Flight payloads generated by
 * react-server-dom-webpack in a child process running under
 * `--conditions react-server` (exactly how the production RSC bundle runs — the
 * react-server and Fizz runtimes cannot share one module graph, which is also why
 * this file is NOT a `.rsc.test.*` file), real manifest JSON files on disk, the
 * real length-prefixed envelope used by the node renderer, the real stream tee in
 * RSCRequestTracker, the real Flight decode, and the real Fizz render through
 * `streamServerRenderedReactComponent`. The ONLY test double is the function that
 * returns the RSC payload stream (`generateRSCPayload` / `getRSCPayloadStream`),
 * which returns the whole payload as one already-buffered chunk — that is the
 * "complete payload" premise under test.
 */

import { execFileSync } from 'child_process';
import * as fs from 'fs';
import * as os from 'os';
import * as path from 'path';
import { PassThrough } from 'stream';
import * as React from 'react';
import { use } from 'react';
import { renderToPipeableStream } from 'react-dom/server';
import type { RailsContextWithServerStreamingCapabilities, RenderParams } from 'react-on-rails/types';
import getReactServerComponent from '../src/getReactServerComponent.server.ts';
import streamServerRenderedReactComponent from '../src/streamServerRenderedReactComponent.ts';
import wrapServerComponentRenderer from '../src/wrapServerComponentRenderer/server.tsx';
import RSCRoute from '../src/RSCRoute.tsx';
import ReactOnRails from '../src/ReactOnRails.node.ts';
import * as ComponentRegistry from '../src/ComponentRegistry.ts';
import LengthPrefixedStreamParser from '../src/parseLengthPrefixedStream.ts';
import { flushMacrotasks } from './testUtils.ts';

jest.setTimeout(30_000);

// ---------------------------------------------------------------------------
// Fixture payloads — real Flight bytes generated under `--conditions react-server`
// ---------------------------------------------------------------------------

type FlightFixture = {
  clientComponentFilePath: string;
  browserModuleId: string;
  payloads: {
    plainServer: string;
    withClientComponent: string;
    withResolvedPromise: string;
    mixedNested: string;
  };
  pendingSplit: { part1: string; part2: string };
};

const SSR_MODULE_ID = 'rsc-ssr-synchrony-client-card-ssr';

let fixture: FlightFixture;
let flight: Record<keyof FlightFixture['payloads'], Buffer>;
let pendingPart1: Buffer;
let pendingPart2: Buffer;
let manifestDir: string;
let clientManifestPath: string;
let serverClientManifestPath: string;

const generateFixture = (): FlightFixture => {
  const generatorPath = path.resolve(__dirname, 'fixtures/rscSsrSynchrony/generateFlightPayloads.mjs');
  const stdout = execFileSync(process.execPath, ['--conditions', 'react-server', generatorPath], {
    encoding: 'utf8',
    maxBuffer: 16 * 1024 * 1024,
  });
  return JSON.parse(stdout) as FlightFixture;
};

// ---------------------------------------------------------------------------
// SSR module registry — how the Fizz side resolves the client reference
// ---------------------------------------------------------------------------

// Single-expression text children keep each rendered string one HTML text node,
// so assertions don't have to account for React's `<!-- -->` text separators.
const CardData = ({ dataPromise }: { dataPromise: Promise<string> }) => <em>{`data:${use(dataPromise)}`}</em>;

// The SSR implementation of the client component referenced inside the Flight
// payloads. `use(dataPromise)` consumes the already-resolved promise serialized
// into the payload — the exact shape issue #4859 flags as likely to break.
const ClientCardSSR = ({ label, dataPromise }: { label: string; dataPromise?: Promise<string> }) => (
  <span className="client-card">
    {`client:${label}`}
    {dataPromise ? <CardData dataPromise={dataPromise} /> : null}
  </span>
);

type WebpackGlobals = {
  __webpack_require__?: (id: string) => unknown;
  __webpack_chunk_load__?: (id: string) => Promise<unknown>;
};

const webpackGlobals = globalThis as WebpackGlobals;

// ---------------------------------------------------------------------------
// Stream + envelope helpers (mirror the node renderer's length-prefixed protocol)
// ---------------------------------------------------------------------------

const toLengthPrefixedEnvelope = (content: Buffer): Buffer => {
  const metadata = JSON.stringify({ consoleReplayScript: '', hasErrors: false, isShellReady: true });
  return Buffer.concat([
    Buffer.from(`${metadata}\t${content.length.toString(16).padStart(8, '0')}\n`, 'utf8'),
    content,
  ]);
};

// The "complete payload" premise: the whole Flight document, already buffered,
// delivered as a single chunk with EOF before any consumer attaches.
const completePayloadStream = (flightBytes: Buffer): PassThrough => {
  const stream = new PassThrough();
  stream.end(toLengthPrefixedEnvelope(flightBytes));
  return stream;
};

// Negative control: part1 (shell + fallback rows) available immediately, part2
// (the late Suspense rows) only after a real macrotask delay.
const pendingPayloadStream = (part1: Buffer, part2: Buffer, delayMs: number): PassThrough => {
  const stream = new PassThrough();
  stream.write(toLengthPrefixedEnvelope(part1));
  setTimeout(() => {
    stream.end(toLengthPrefixedEnvelope(part2));
  }, delayMs);
  return stream;
};

// ---------------------------------------------------------------------------
// Tripwires
// ---------------------------------------------------------------------------

type Tripwire = { fired: () => boolean; disarm: () => void };

const armSetTimeoutTripwire = (): Tripwire => {
  let fired = false;
  const timer = setTimeout(() => {
    fired = true;
  }, 0);
  return { fired: () => fired, disarm: () => clearTimeout(timer) };
};

const armSetImmediateTripwire = (): Tripwire => {
  let fired = false;
  const immediate = setImmediate(() => {
    fired = true;
  });
  return { fired: () => fired, disarm: () => clearImmediate(immediate) };
};

// ---------------------------------------------------------------------------
// Decode-level helpers (issue cases 1–4)
// ---------------------------------------------------------------------------

type DecodeModule = { default: typeof getReactServerComponent };

const decodeCompletePayload = (
  flightBytes: Buffer,
  decodeModule: DecodeModule = { default: getReactServerComponent },
): Promise<React.ReactNode> => {
  const railsContext = {
    reactClientManifestFileName: clientManifestPath,
    reactServerClientManifestFileName: serverClientManifestPath,
    getRSCPayloadStream: () => Promise.resolve(completePayloadStream(flightBytes)),
  } as unknown as RailsContextWithServerStreamingCapabilities;

  return decodeModule.default(railsContext)({
    componentName: 'SynchronyProbe',
    componentProps: {},
  }) as Promise<React.ReactNode>;
};

// Renders a decoded element through Fizz and returns the COMPLETE html (waits
// for onAllReady) — used to verify decoded trees, not to measure timing.
const renderElementToHtml = (element: React.ReactNode): Promise<string> =>
  new Promise((resolve, reject) => {
    const chunks: Buffer[] = [];
    const sink = new PassThrough();
    sink.on('data', (chunk: Buffer) => chunks.push(chunk));
    sink.on('end', () => resolve(Buffer.concat(chunks).toString('utf8')));
    sink.on('error', reject);
    const stream = renderToPipeableStream(element, {
      onAllReady() {
        stream.pipe(sink);
      },
      onError(error) {
        reject(error instanceof Error ? error : new Error(String(error)));
      },
    });
  });

// ---------------------------------------------------------------------------
// E2E helpers (issue cases 5–6) — the full streamServerRenderedReactComponent path
// ---------------------------------------------------------------------------

const testingRailsContext = () =>
  ({
    serverSide: true,
    componentSpecificMetadata: { renderRequestId: 'rsc-ssr-synchrony' },
    serverSideRSCPayloadParameters: {},
    reactClientManifestFileName: clientManifestPath,
    reactServerClientManifestFileName: serverClientManifestPath,
  }) as unknown as RenderParams['railsContext'];

const renderThroughFullPipeline = (payloadStreamFactory: () => PassThrough) =>
  streamServerRenderedReactComponent({
    name: 'RscSynchronyRoute',
    domNodeId: 'rsc-synchrony-node',
    trace: false,
    props: {},
    throwJsErrors: true,
    railsContext: testingRailsContext(),
    generateRSCPayload: () => Promise.resolve(payloadStreamFactory()),
  } as unknown as RenderParams);

type CollectedRender = {
  htmlSoFar: () => string;
  ended: () => boolean;
  finished: Promise<string>;
};

// Parses the render stream's length-prefixed envelopes as they arrive so tests
// can inspect "what has been flushed so far" at macrotask granularity.
const collectRenderStream = (stream: NodeJS.ReadableStream): CollectedRender => {
  const parser = new LengthPrefixedStreamParser();
  const decoder = new TextDecoder();
  let html = '';
  let ended = false;
  const finished = new Promise<string>((resolve, reject) => {
    stream.on('data', (chunk: Buffer) => {
      try {
        parser.feed(chunk, (content) => {
          html += decoder.decode(content);
        });
      } catch (error) {
        reject(error instanceof Error ? error : new Error(String(error)));
      }
    });
    stream.on('end', () => {
      ended = true;
      resolve(html);
    });
    stream.on('error', reject);
  });
  return { htmlSoFar: () => html, ended: () => ended, finished };
};

const macrotaskTurnsUntil = async (predicate: () => boolean, maxTurns: number): Promise<number> => {
  let turns = 0;
  while (!predicate() && turns < maxTurns) {
    // eslint-disable-next-line no-await-in-loop -- deliberately sequential: each turn is one macrotask
    await flushMacrotasks();
    turns += 1;
  }
  return turns;
};

// The complete-payload E2E budget, in macrotask turns (see the header: Fizz
// flushes via setImmediate, so the whole response lands before the FIRST
// setTimeout(0)-based turn completes; 3 leaves headroom against incidental
// scheduling noise without masking a real regression, which costs a pending
// promise/timer and blows well past it).
const COMPLETE_RENDER_TURN_BUDGET = 3;

// ---------------------------------------------------------------------------
// Setup
// ---------------------------------------------------------------------------

beforeAll(async () => {
  fixture = generateFixture();
  flight = {
    plainServer: Buffer.from(fixture.payloads.plainServer, 'base64'),
    withClientComponent: Buffer.from(fixture.payloads.withClientComponent, 'base64'),
    withResolvedPromise: Buffer.from(fixture.payloads.withResolvedPromise, 'base64'),
    mixedNested: Buffer.from(fixture.payloads.mixedNested, 'base64'),
  };
  pendingPart1 = Buffer.from(fixture.pendingSplit.part1, 'base64');
  pendingPart2 = Buffer.from(fixture.pendingSplit.part2, 'base64');

  // Real manifest files on disk. loadJsonFile resolves absolute paths as-is, so
  // the tests exercise the real fs-backed manifest loading (no fs mocking).
  manifestDir = fs.mkdtempSync(path.join(os.tmpdir(), 'rsc-ssr-synchrony-'));
  clientManifestPath = path.join(manifestDir, 'react-client-manifest.json');
  serverClientManifestPath = path.join(manifestDir, 'react-server-client-manifest.json');
  fs.writeFileSync(
    clientManifestPath,
    JSON.stringify({
      filePathToModuleMetadata: {
        [fixture.clientComponentFilePath]: { id: fixture.browserModuleId, chunks: [] },
      },
      moduleLoading: { prefix: '', crossOrigin: null },
    }),
  );
  fs.writeFileSync(
    serverClientManifestPath,
    JSON.stringify({
      filePathToModuleMetadata: {
        [fixture.clientComponentFilePath]: { id: SSR_MODULE_ID, chunks: [] },
      },
      moduleLoading: { prefix: '', crossOrigin: null },
    }),
  );

  // Wire the webpack module system the Flight SSR client uses to load the client
  // component's server-bundle implementation. Synchronous, like a standard
  // (non-async-module) webpack server bundle.
  webpackGlobals.__webpack_require__ = (id: string) => {
    if (id !== SSR_MODULE_ID) {
      throw new Error(`Unexpected SSR module id: ${id}`);
    }
    return { default: ClientCardSSR };
  };
  webpackGlobals.__webpack_chunk_load__ = () => Promise.resolve();

  // Register the production-style component wrapper once: this is exactly what
  // registerServerComponent/server does internally (RSCRoute inside
  // wrapServerComponentRenderer), spelled out so the test registers through
  // ReactOnRails.node like the server bundle does.
  ComponentRegistry.clear();
  ReactOnRails.register({
    RscSynchronyRoute: wrapServerComponentRenderer(
      (props: unknown) => (
        <RSCRoute componentName="ServerCard" componentProps={props as Record<string, unknown>} />
      ),
      'RscSynchronyRoute',
    ) as unknown as Parameters<typeof ReactOnRails.register>[0][string],
  });

  // Warm-up: one decode + one full-pipeline render. This loads the manifest
  // files (module-level caches in getReactServerComponent.server.ts and
  // cache/manifestStylesheets.ts), putting the process in the warm steady state
  // the zero-macrotask contract is defined for. Cold behavior is tested
  // explicitly, in an isolated module registry, below.
  await decodeCompletePayload(flight.withClientComponent);
  await collectRenderStream(renderThroughFullPipeline(() => completePayloadStream(flight.plainServer)))
    .finished;
});

afterAll(() => {
  delete webpackGlobals.__webpack_require__;
  delete webpackGlobals.__webpack_chunk_load__;
  ComponentRegistry.clear();
  if (manifestDir) {
    fs.rmSync(manifestDir, { recursive: true, force: true });
  }
});

// ---------------------------------------------------------------------------
// Cases 1–4: decode-level zero-macrotask contract (warm manifests)
// ---------------------------------------------------------------------------

describe('complete payload decodes within the same macrotask turn (warm manifests)', () => {
  const expectDecodeBeatsTripwires = async (flightBytes: Buffer): Promise<React.ReactNode> => {
    const immediateTripwire = armSetImmediateTripwire();
    const timeoutTripwire = armSetTimeoutTripwire();
    try {
      const element = await decodeCompletePayload(flightBytes);
      expect(immediateTripwire.fired()).toBe(false);
      expect(timeoutTripwire.fired()).toBe(false);
      return element;
    } finally {
      immediateTripwire.disarm();
      timeoutTripwire.disarm();
    }
  };

  it('case 1: plain server-component payload (baseline)', async () => {
    const element = await expectDecodeBeatsTripwires(flight.plainServer);

    const html = await renderElementToHtml(element);
    expect(html).toContain('<h1>PLAIN_HEADER_MARKER</h1>');
    expect(html).toContain('<p>PLAIN_TEXT_MARKER</p>');
  });

  it('case 2: payload with a client component resolves through the manifest without a macrotask hop', async () => {
    const element = await expectDecodeBeatsTripwires(flight.withClientComponent);

    const html = await renderElementToHtml(element);
    expect(html).toContain('<h2>SERVER_WRAPPER_MARKER</h2>');
    expect(html).toContain('client:CARD_LABEL_MARKER');
  });

  it('case 2 (repeat): a second decode against the warm module cache holds the same contract', async () => {
    const element = await expectDecodeBeatsTripwires(flight.withClientComponent);

    const html = await renderElementToHtml(element);
    expect(html).toContain('client:CARD_LABEL_MARKER');
  });

  it('case 3: payload with already-resolved promises settles on microtasks only', async () => {
    const element = await expectDecodeBeatsTripwires(flight.withResolvedPromise);

    const html = await renderElementToHtml(element);
    expect(html).toContain('awaited:AWAITED_VALUE_MARKER');
    expect(html).toContain('<p>PROMISE_CHILD_MARKER</p>');
  });

  it('case 4: client component with a resolved-promise prop inside <Suspense> (nested/mixed)', async () => {
    const element = await expectDecodeBeatsTripwires(flight.mixedNested);

    const html = await renderElementToHtml(element);
    expect(html).toContain('<h2>MIXED_SHELL_MARKER</h2>');
    expect(html).toContain('client:MIXED_CARD_MARKER');
    expect(html).toContain('data:MIXED_DATA_MARKER');
    expect(html).toContain('awaited:AWAITED_VALUE_MARKER');
    // The Suspense boundary resolved during the render — never client-swapped.
    expect(html).not.toContain('<p>INNER_FALLBACK_MARKER</p>');
    expect(html).not.toContain('<!--$?-->');
  });
});

// ---------------------------------------------------------------------------
// Case 2 (cold half): first decode in a process pays only the manifest load
// ---------------------------------------------------------------------------

describe('cold manifest cache', () => {
  it('first decode loads manifests from disk, still yields the full tree, and warms the process', async () => {
    await jest.isolateModulesAsync(async () => {
      // Fresh module registry: getReactServerComponent.server.ts's module-level
      // clientRendererPromise and loadJsonFile's cache start empty — the real
      // first-render-in-a-new-renderer-process situation.
      // eslint-disable-next-line global-require, @typescript-eslint/no-var-requires
      const freshModule = require('../src/getReactServerComponent.server.ts') as DecodeModule;

      // Cold: the manifest fs reads legitimately cross macrotask boundaries, so
      // there is deliberately NO tripwire here (see the file header). What must
      // hold is that the decoded tree is complete and correct.
      const coldElement = await decodeCompletePayload(flight.mixedNested, freshModule);
      const coldHtml = await renderElementToHtml(coldElement);
      expect(coldHtml).toContain('client:MIXED_CARD_MARKER');
      expect(coldHtml).toContain('data:MIXED_DATA_MARKER');
      expect(coldHtml).not.toContain('<p>INNER_FALLBACK_MARKER</p>');

      // One decode is enough to warm the process: the very next decode meets the
      // full zero-macrotask contract.
      const immediateTripwire = armSetImmediateTripwire();
      const timeoutTripwire = armSetTimeoutTripwire();
      try {
        const warmElement = await decodeCompletePayload(flight.withClientComponent, freshModule);
        expect(immediateTripwire.fired()).toBe(false);
        expect(timeoutTripwire.fired()).toBe(false);
        const warmHtml = await renderElementToHtml(warmElement);
        expect(warmHtml).toContain('client:CARD_LABEL_MARKER');
      } finally {
        immediateTripwire.disarm();
        timeoutTripwire.disarm();
      }
    });
  });
});

// ---------------------------------------------------------------------------
// Case 5: end-to-end through Fizz — first flush carries the real markup
// ---------------------------------------------------------------------------

describe('end-to-end: complete payload through streamServerRenderedReactComponent', () => {
  it('case 5: renders real markup with no fallback, no pending boundary, and no completion script', async () => {
    const collected = collectRenderStream(
      renderThroughFullPipeline(() => completePayloadStream(flight.mixedNested)),
    );

    const turns = await macrotaskTurnsUntil(collected.ended, COMPLETE_RENDER_TURN_BUDGET + 1);
    expect(collected.ended()).toBe(true);
    expect(turns).toBeLessThanOrEqual(COMPLETE_RENDER_TURN_BUDGET);

    const html = await collected.finished;
    // The real content is in the first (and only) flush...
    expect(html).toContain('<h2>MIXED_SHELL_MARKER</h2>');
    expect(html).toContain('client:MIXED_CARD_MARKER');
    expect(html).toContain('data:MIXED_DATA_MARKER');
    expect(html).toContain('awaited:AWAITED_VALUE_MARKER');
    // ...and nothing anywhere in the response says "content wasn't ready":
    // no rendered fallback, no pending-boundary comment, no client-side
    // boundary-completion runtime, no template placeholder.
    expect(html).not.toContain('<p>INNER_FALLBACK_MARKER</p>');
    expect(html).not.toContain('<!--$?-->');
    expect(html).not.toContain('$RC');
    expect(html).not.toContain('<template');
    // The RSC payload embedding (hydration data) still happened.
    expect(html).toContain('REACT_ON_RAILS_RSC_PAYLOADS');
  });

  it('case 5 (baseline shape): plain server payload streams as one complete flush', async () => {
    const collected = collectRenderStream(
      renderThroughFullPipeline(() => completePayloadStream(flight.plainServer)),
    );

    const turns = await macrotaskTurnsUntil(collected.ended, COMPLETE_RENDER_TURN_BUDGET + 1);
    expect(collected.ended()).toBe(true);
    expect(turns).toBeLessThanOrEqual(COMPLETE_RENDER_TURN_BUDGET);

    const html = await collected.finished;
    expect(html).toContain('<h1>PLAIN_HEADER_MARKER</h1>');
    expect(html).toContain('<p>PLAIN_TEXT_MARKER</p>');
    expect(html).not.toContain('<!--$?-->');
    expect(html).not.toContain('$RC');
  });
});

// ---------------------------------------------------------------------------
// Case 6: negative control — a genuinely pending payload MUST produce a fallback
// ---------------------------------------------------------------------------

describe('negative control: genuinely pending payload', () => {
  it('case 6: first flush carries the Suspense fallback; completion arrives in a later macrotask', async () => {
    const collected = collectRenderStream(
      renderThroughFullPipeline(() => pendingPayloadStream(pendingPart1, pendingPart2, 10)),
    );

    // Give the pipeline the same budget the complete-payload cases get. The late
    // rows arrive ~10ms in, so the stream must still be open here...
    await macrotaskTurnsUntil(
      () => collected.htmlSoFar().includes('PENDING_SHELL_MARKER'),
      COMPLETE_RENDER_TURN_BUDGET + 1,
    );
    expect(collected.ended()).toBe(false);

    // ...and what HAS flushed is the shell with the rendered fallback and an
    // open (pending) Suspense boundary — the exact degradation cases 1–5 exist
    // to prevent for complete payloads. This proves the shape assertions above
    // can fail: an implementation that just blocked forever would fail here.
    const firstFlushHtml = collected.htmlSoFar();
    expect(firstFlushHtml).toContain('<h1>PENDING_SHELL_MARKER</h1>');
    expect(firstFlushHtml).toContain('<p>PENDING_FALLBACK_MARKER</p>');
    expect(firstFlushHtml).toContain('<!--$?-->');
    expect(firstFlushHtml).not.toContain('late:PENDING_LATE_MARKER');

    // Once the pending rows land, React streams the real content plus the
    // boundary-completion script that swaps out the fallback.
    const fullHtml = await collected.finished;
    expect(fullHtml).toContain('late:PENDING_LATE_MARKER');
    expect(fullHtml).toContain('$RC');
  });
});
